    printf("T007 seq_start_init=%d type=%d\n", r7, ev.type);
    yaml_event_delete(&ev);

    int r8 = yaml_sequence_end_event_initialize(&ev);
    printf("T007 seq_end_init=%d type=%d\n", r8, ev.type);
