    yaml_emitter_emit(&emitter, &ev);

    yaml_document_end_event_initialize(&ev, 1);
    yaml_emitter_emit(&emitter, &ev);

    yaml_stream_end_event_initialize(&ev);
    yaml_emitter_emit(&emitter, &ev);

    yaml_emitter_flush(&emitter);
    buf[written] = '\0';
    printf("T038 output=%s\n", (char *)buf);
    yaml_emitter_delete(&emitter);
}

